/**
 * Random-move scrambles in the WCA style: face turns only, no two
 * consecutive turns of the same face, and no three consecutive turns on the
 * same axis (e.g. "R L R"), which would cancel into fewer effective moves.
 *
 * Official WCA competition scrambles are random-state (generated by a
 * solver); random-move scrambles of 25 turns are the common lightweight
 * substitute.
 */

const FACES = ['U', 'D', 'L', 'R', 'F', 'B'];
const AXIS = { U: 0, D: 0, L: 1, R: 1, F: 2, B: 2 };
const AMOUNTS = [1, -1, 2];

/**
 * @param {{ length?: number, rng?: () => number }} [options] rng must return values in [0, 1), like Math.random
 * @returns {import('./cube.js').Move[]}
 */
export function randomScramble({ length = 25, rng = Math.random } = {}) {
  const pick = (items) => items[Math.floor(rng() * items.length)];
  const moves = [];
  while (moves.length < length) {
    const prev = moves.at(-1)?.name;
    const prev2 = moves.at(-2)?.name;
    const allowed = FACES.filter((f) => f !== prev
      && !(prev2 && AXIS[f] === AXIS[prev] && AXIS[f] === AXIS[prev2]));
    moves.push({ name: pick(allowed), amount: pick(AMOUNTS) });
  }
  return moves;
}
